INSERT INTO courses (id, course_code, title, provider, description, skills_covered, difficulty, duration, language, rating, thumbnail, category, modules)
VALUES
    ('course-1', 'NSSTA-TPAC-101', 'Fundamentals of Official Statistics', 'NSSTA', 'Comprehensive introduction to official statistics, principles, frameworks and practices used in national statistical systems.', '["Survey Design", "Sampling", "Data Quality", "Metadata Standards"]'::jsonb, 'Beginner', '8 weeks', 'English', 4.5, '📊', 'Statistical', '[{"title": "Introduction to Official Statistical System", "duration": "1h", "type": "lesson", "summary": "Overview of the National Statistical Office and statistical system of India"}, {"title": "Statistical Principles & Methodologies", "duration": "2h", "type": "lesson", "summary": "Fundamental principles, definitions and classifications"}, {"title": "Data Quality Frameworks", "duration": "1h", "type": "lesson", "summary": "Quality dimensions, data quality assessment frameworks"}, {"title": "Metadata & Dissemination Standards", "duration": "1h", "type": "lesson", "summary": "Statistical metadata standards, documentation practices"}, {"title": "Fundamentals Assessment", "duration": "30m", "type": "quiz", "summary": "Quick knowledge check on core concepts"}]'::jsonb),
    ('course-2', 'NSSTA-TPAC-202', 'Survey Design and Sampling', 'NSSTA', 'Advanced course on survey methodology including questionnaire design, sampling frames, stratified sampling and estimation.', '["Survey Design", "Sampling", "Data Quality"]'::jsonb, 'Intermediate', '6 weeks', 'English', 4.7, '🎯', 'Statistical', '[{"title": "Sampling Frames & Design", "duration": "2h", "type": "lesson", "summary": "Building sampling frames and choosing survey designs"}, {"title": "Questionnaire Development", "duration": "1.5h", "type": "lesson", "summary": "Question design, pretesting and cognitive interviewing"}, {"title": "Stratified & Cluster Sampling", "duration": "2h", "type": "lesson", "summary": "Variance estimation for complex sample designs"}, {"title": "Survey Operations & Field Work", "duration": "1h", "type": "lab", "summary": "Field operations and non-sampling error control"}, {"title": "Survey Design Project", "duration": "45m", "type": "quiz", "summary": "Design a survey for a given objective"}]'::jsonb),
    ('course-3', 'NSSTA-TPAC-203', 'National Accounts Compilation', 'NSSTA', 'Compilation of national accounts, GDP estimates and SNA frameworks for official statistics.', '["National Accounts", "Data Quality", "Metadata Standards"]'::jsonb, 'Advanced', '10 weeks', 'English', 4.6, '💹', 'Statistical', '[{"title": "System of National Accounts (SNA)", "duration": "3h", "type": "lesson", "summary": "SNA framework and accounting identities"}, {"title": "GDP Estimation Methods", "duration": "3h", "type": "lesson", "summary": "Production, income and expenditure approaches"}, {"title": "Blue Book Compilation", "duration": "2h", "type": "lab", "summary": "Hands-on compilation exercise from source data"}, {"title": "Revisions & Quality Assurance", "duration": "1.5h", "type": "lesson", "summary": "Benchmarking, revisions policy and QA"}]'::jsonb),
    ('course-4', 'NSSTA-TPAC-204', 'Price Statistics and CPI/WPI', 'NSSTA', 'Construction of Consumer Price Index (CPI), Wholesale Price Index (WPI) and inflation measurement.', '["Price Statistics", "Sampling", "Data Quality"]'::jsonb, 'Intermediate', '5 weeks', 'English', 4.4, '🏷️', 'Statistical', '[{"title": "Index Number Theory", "duration": "2h", "type": "lesson", "summary": "Laspeyres, Paasche and Fisher index formulas"}, {"title": "CPI Construction", "duration": "2h", "type": "lab", "summary": "Compute CPI from price quotations"}, {"title": "Inflation Measurement & Uses", "duration": "1.5h", "type": "lesson", "summary": "Interpreting inflation and its policy uses"}]'::jsonb),
    ('course-5', 'NSSTA-TPAC-205', 'Labour and Agricultural Statistics', 'NSSTA', 'Labour force surveys, employment statistics and agricultural statistics compilation.', '["Labour Statistics", "Agricultural Statistics", "Survey Design", "Sampling"]'::jsonb, 'Intermediate', '6 weeks', 'English', 4.3, '🌾', 'Statistical', '[{"title": "Labour Force Surveys (PLFS)", "duration": "2h", "type": "lesson", "summary": "Survey design of PLFS and labour measures"}, {"title": "Agricultural Statistics", "duration": "2h", "type": "lesson", "summary": "Land use, crop area and production statistics"}, {"title": "Estimation & Dissemination", "duration": "1.5h", "type": "lab", "summary": "Estimate employment indicators from sample data"}]'::jsonb),
    ('course-6', 'NSSTA-TPAC-206', 'SDG Indicators and Metadata', 'NSSTA', 'SDG indicator framework, national baselines, metadata standards and reporting.', '["SDG Indicators", "Metadata Standards", "Data Quality"]'::jsonb, 'Beginner', '4 weeks', 'English', 4.5, '🌍', 'Statistical', '[{"title": "SDG Indicator Framework", "duration": "2h", "type": "lesson", "summary": "Global indicator framework and tiers"}, {"title": "Metadata & Data Reporting", "duration": "1.5h", "type": "lesson", "summary": "Reporting mechanisms, metadata standards"}, {"title": "SDG Data Exercise", "duration": "1h", "type": "lab", "summary": "Populate indicators for sample districts"}]'::jsonb),
    ('course-7', 'iGOT-MOD-301', 'Python for Government Data Analysis', 'iGOT Karmayogi', 'Learn Python programming tailored for government data analysis: pandas, numpy, data cleaning and automated reporting.', '["Python", "Data Visualization", "Data Quality"]'::jsonb, 'Beginner', '10 weeks', 'English', 4.6, '🐍', 'Technical', '[{"title": "Python Basics", "duration": "2h", "type": "lesson", "summary": "Variables, data types, control flow", "code": "ages = [28, 34, 29, 41, 36]\ntotal = 0\nfor a in ages:\n    total += a\nprint(''Count:'', len(ages))\nprint(''Sum:'', total)\nprint(''Mean age:'', round(total / len(ages), 2))", "sandbox": "python"}, {"title": "Pandas Fundamentals", "duration": "2h", "type": "lab", "summary": "DataFrames, filtering and aggregation", "code": "survey = [\n    {''district'': ''Alwar'', ''households'': 420, ''dept'': ''NSSO''},\n    {''district'': ''Mysuru'', ''households'': 515, ''dept'': ''Census''},\n    {''district'': ''Nashik'', ''households'': 310, ''dept'': ''NSSTA''},\n    {''district'': ''Ludhiana'', ''households'': 600, ''dept'': ''NSSO''},\n]\nnss = [r[''households''] for r in survey if r[''dept''] == ''NSSO'']\nprint(''NSSO rows:'', len(nss))\nprint(''Average NSSO households:'', round(sum(nss) / len(nss), 1))", "sandbox": "python"}, {"title": "Data Cleaning with pandas", "duration": "2h", "type": "lab", "summary": "Missing values, types, deduplication", "code": "raw = [''3.1'', None, ''2.8'', ''3.6'', ''x'', ''3.9'']\ncleaned = []\nfor v in raw:\n    try:\n        cleaned.append(float(v))\n    except (TypeError, ValueError):\n        print(''Dropped bad value:'', v)\nprint(''Cleaned values:'', cleaned)\nprint(''Mean of clean data:'', round(sum(cleaned) / len(cleaned), 2))", "sandbox": "python"}, {"title": "Automated Reporting", "duration": "1.5h", "type": "lab", "summary": "Batch report generation for NSSO data", "code": "titles = [''Alwar'', ''Mysuru'', ''Nashik'']\nrates = [70.7, 72.6, 80.9]\nprint(''District | Literacy | Status'')\nfor d, r in zip(titles, rates):\n    status = ''High'' if r >= 75 else ''Needs focus''\n    print(f''{d:8s} | {r:8.1f} | {status}'')\nprint(''Average literacy:'', round(sum(rates) / len(rates), 1))", "sandbox": "python"}, {"title": "Python Assessment", "duration": "30m", "type": "quiz", "summary": "Data analysis quiz in Python"}]'::jsonb),
    ('course-8', 'iGOT-MOD-302', 'SQL for Statistical Databases', 'iGOT Karmayogi', 'Master SQL for managing and querying statistical databases - joins, aggregations and design patterns.', '["SQL", "Data Quality"]'::jsonb, 'Intermediate', '6 weeks', 'English', 4.4, '🗃️', 'Technical', '[{"title": "SQL Fundamentals", "duration": "2h", "type": "lesson", "summary": "SELECT, WHERE, filtering and ordering", "code": "SELECT name, literacy FROM districts WHERE literacy > 75 ORDER BY literacy DESC", "sandbox": "sql"}, {"title": "Joins & Aggregations", "duration": "2h", "type": "lab", "summary": "Joins, GROUP BY, window functions", "code": "SELECT AVG(literacy) FROM districts", "sandbox": "sql"}, {"title": "Statistical Database Design", "duration": "1.5h", "type": "lesson", "summary": "Normalization and schema patterns"}, {"title": "SQL Assessment", "duration": "30m", "type": "quiz", "summary": "Write queries against a statistical schema"}]'::jsonb),
    ('course-9', 'iGOT-MOD-303', 'Data Visualization with Power BI', 'iGOT Karmayogi', 'Create compelling dashboards and reports with Power BI for government reporting.', '["Data Visualization", "SQL"]'::jsonb, 'Intermediate', '5 weeks', 'English', 4.3, '📈', 'Technical', '[{"title": "Visual Design Principles", "duration": "1.5h", "type": "lesson", "summary": "Choosing the right chart for the message"}, {"title": "Power BI Reports", "duration": "2h", "type": "lab", "summary": "Build interactive dashboards from survey data"}, {"title": "Dashboard for Policy Makers", "duration": "1.5h", "type": "lab", "summary": "Storytelling with official statistics"}]'::jsonb),
    ('course-10', 'iGOT-MOD-304', 'Introduction to Artificial Intelligence', 'iGOT Karmayogi', 'Foundation course on AI concepts, machine learning basics and applications in government.', '["AI/ML", "Python"]'::jsonb, 'Beginner', '8 weeks', 'English', 4.8, '🤖', 'Technical', '[{"title": "AI Concepts & Ethics of AI", "duration": "2h", "type": "lesson", "summary": "AI paradigms and responsible AI principles"}, {"title": "Machine Learning Basics", "duration": "2h", "type": "lesson", "summary": "Regression, classification, evaluation"}, {"title": "ML Lab", "duration": "2h", "type": "lab", "summary": "Train a simple classifier on sample data", "code": "pairs = [(1, 12), (2, 15), (3, 17), (4, 20), (5, 22), (6, 25)]\nxs = [p[0] for p in pairs]\nys = [p[1] for p in pairs]\nn = len(xs)\nxbar = sum(xs) / n\nybar = sum(ys) / n\nslope = sum((x - xbar) * (y - ybar) for x, y in pairs) / sum((x - xbar) ** 2 for x in xs)\nintercept = ybar - slope * xbar\nprint(''Slope:'', round(slope, 3))\nprint(''Intercept:'', round(intercept, 2))\nprint(''Predicted score after 8h:'', round(slope * 8 + intercept, 1))", "sandbox": "python"}, {"title": "AI in Official Statistics", "duration": "1.5h", "type": "lesson", "summary": "Use cases: predictive analytics, anomaly detection"}, {"title": "AI Assessment", "duration": "30m", "type": "quiz", "summary": "Check understanding of ML fundamentals"}]'::jsonb),
    ('course-11', 'iGOT-MOD-305', 'Advanced Machine Learning for Statistics', 'iGOT Karmayogi', 'Apply ML to regression, classification, clustering and time series forecasting for official data.', '["AI/ML", "Python", "Data Visualization"]'::jsonb, 'Advanced', '12 weeks', 'English', 4.9, '🧠', 'Technical', '[{"title": "Advanced Regression & Time Series", "duration": "3h", "type": "lesson", "summary": "Forecasting official time series"}, {"title": "Classification & Clustering", "duration": "2h", "type": "lab", "summary": "Classification pipelines and clustering census data", "code": "census = [\n    (''Alwar'', 70.7),\n    (''Mysuru'', 72.6),\n    (''Nashik'', 80.9),\n    (''Ludhiana'', 82.2),\n    (''Varanasi'', 70.3),\n]\nscores = [r[1] for r in census]\nmean_score = sum(scores) / len(scores)\nfor name, score in census:\n    label = ''high'' if score >= mean_score else ''low''\n    print(name, ''-> '' + label, ''(mean'', round(mean_score, 1), '')'')", "sandbox": "python"}, {"title": "Model Evaluation & Deployment", "duration": "2h", "type": "lesson", "summary": "Validation, drift and deployment"}]'::jsonb),
    ('course-12', 'NSSTA-TPAC-207', 'Data Privacy and Cybersecurity', 'NSSTA', 'DPDP Act, government cybersecurity frameworks and data protection practices.', '["Data Privacy", "Cybersecurity", "Digital Signatures"]'::jsonb, 'Intermediate', '4 weeks', 'English', 4.2, '🔒', 'Digital Governance', '[{"title": "DPDP Act Explained", "duration": "2h", "type": "lesson", "summary": "Key provisions and obligations for data fiduciaries"}, {"title": "Cybersecurity Fundamentals", "duration": "2h", "type": "lesson", "summary": "Threats, encryption, access control"}, {"title": "Secure Data Handling Lab", "duration": "1.5h", "type": "lab", "summary": "Incident response and secure handling scenarios"}]'::jsonb),
    ('course-13', 'iGOT-MOD-306', 'Leadership in Digital Governance', 'iGOT Karmayogi', 'Leadership skills to drive digital transformation in government.', '["Leadership", "Communication", "Change Management"]'::jsonb, 'Advanced', '6 weeks', 'English', 4.5, '🏛️', 'Behavioural', '[{"title": "Leading Digital Transformation", "duration": "2h", "type": "lesson", "summary": "Vision, culture and digital leadership"}, {"title": "Change Management", "duration": "2h", "type": "lesson", "summary": "Models and execution of change"}, {"title": "Stakeholder Communication", "duration": "1.5h", "type": "lab", "summary": "Practical communication simulations"}]'::jsonb),
    ('course-14', 'NSSTA-TPAC-208', 'Effective Communication for Officials', 'NSSTA', 'Professional communication: report writing, presentations, stakeholder engagement and coordination.', '["Communication", "Ethics"]'::jsonb, 'Beginner', '3 weeks', 'Hindi', 4.1, '💬', 'Behavioural', '[{"title": "Writing for the Public Service", "duration": "1.5h", "type": "lesson", "summary": "Official writing, notes and drafting"}, {"title": "Presentations & Meetings", "duration": "1.5h", "type": "lab", "summary": "Effective presentations and facilitation"}]'::jsonb),
    ('course-15', 'iGOT-MOD-307', 'R Programming for Statistics', 'iGOT Karmayogi', 'Statistical computing with R: tidyverse, statistical tests, and reproducible reporting.', '["R", "Data Visualization"]'::jsonb, 'Intermediate', '8 weeks', 'English', 4.4, '📐', 'Technical', '[{"title": "R Fundamentals", "duration": "2h", "type": "lesson", "summary": "Vectors, data frames and functions"}, {"title": "Statistical Tests in R", "duration": "2h", "type": "lab", "summary": "Hypothesis testing and regression in R"}, {"title": "Reproducible Reports", "duration": "1.5h", "type": "lab", "summary": "R Markdown for official reporting"}]'::jsonb),
    ('course-16', 'iGOT-MOD-308', 'Cloud Computing and Digital Infrastructure', 'iGOT Karmayogi', 'Cloud platforms, government cloud (Meghraj), modern digital infrastructure and interoperability.', '["Cloud Computing", "Government Cloud", "Digital Public Infrastructure", "APIs and Open Data"]'::jsonb, 'Beginner', '6 weeks', 'English', 4.3, '☁️', 'Digital Governance', '[{"title": "Cloud Fundamentals", "duration": "2h", "type": "lesson", "summary": "IaaS, PaaS, SaaS and security in the cloud"}, {"title": "Government Cloud Meghraj", "duration": "1.5h", "type": "lesson", "summary": "GI Cloud and empanelment"}, {"title": "APIs & Open Data", "duration": "2h", "type": "lab", "summary": "Publish and consume government data APIs"}]'::jsonb),
    ('course-17', 'NSSTA-TPAC-209', 'GIS for Official Statistics', 'NSSTA', 'Geographic information systems, spatial analysis and mapping for official statistics.', '["GIS", "Data Visualization"]'::jsonb, 'Intermediate', '5 weeks', 'English', 4.2, '🗺️', 'Technical', '[{"title": "GIS Fundamentals", "duration": "2h", "type": "lesson", "summary": "Coordinate systems, layers and data models"}, {"title": "Spatial Analysis & Mapping", "duration": "2h", "type": "lab", "summary": "Choropleth and thematic mapping of district data"}]'::jsonb)
INSERT INTO labs (id, title, category, description, icon, exercises)
VALUES
    ('lab-python', 'Python Data Lab', 'Technical', 'Run Python snippets to explore data analysis fundamentals - variables, lists, loops, dictionaries and basic statistics.', '🐍', '[{"title": "Basics", "code": "ages = [28, 34, 29, 41, 36]\nprint(''Mean age:'', sum(ages) / len(ages))"}, {"title": "Statistics", "code": "import statistics\nvalues = [3.1, 2.8, 3.6, 3.9, 2.4]\nprint(''Mean:'', statistics.mean(values))\nprint(''Median:'', statistics.median(values))\nprint(''Variance:'', round(statistics.variance(values), 3))"}]'),
    ('lab-sql', 'SQL Query Lab', 'Technical', 'Query a real district-level census dataset with SELECT, WHERE, GROUP BY and JOIN.', '🗃️', '[{"table": "districts", "rows": [["id", "name", "state", "population", "literacy"], [1, "Alwar", "Rajasthan", 3674179, 70.7], [2, "Mysuru", "Karnataka", 3054822, 72.6], [3, "Nashik", "Maharashtra", 6109052, 80.9], [4, "Ludhiana", "Punjab", 3498739, 82.2], [5, "Varanasi", "Uttar Pradesh", 3676841, 70.3], [6, "Thrissur", "Kerala", 3121200, 95.1]]}, {"table": "samples", "rows": [["district_id", "households_surveyed", "dept"], [1, 420, "NSSO"], [2, 515, "Census"], [3, 310, "NSSTA"], [4, 600, "NSSO"], [5, 275, "Census"], [6, 505, "NSSTA"]]}]'),
    ('lab-viz', 'Data Visualization Lab', 'Technical', 'Build a chart with your own numbers. Try literacy rates by district or competitor skill levels.', '📈', '[{"preset": "Literacy by District", "labels": ["Alwar", "Mysuru", "Nashik", "Ludhiana", "Varanasi", "Thrissur"], "values": [70.7, 72.6, 80.9, 82.2, 70.3, 95.1], "type": "bar"}]'),
    ('lab-ml', 'AI/ML Playground', 'Technical', 'Fit a linear regression to data points and see predicted values - the same math behind forecasting.', '🤖', '[{"title": "Linear Regression", "x": [1, 2, 3, 4, 5, 6], "y": [12, 15, 17, 20, 22, 25], "explain": "hours studied -> score prediction"}]'),
    ('lab-gis', 'GIS Mapping Sandbox', 'Technical', 'Visualize district data as a thematic map. Explore how GIS layers work for official statistics.', '🗺️', '[{"preset": "District Data", "points": [["Alwar", 70.7], ["Mysuru", 72.6], ["Nashik", 80.9], ["Ludhiana", 82.2], ["Varanasi", 70.3], ["Thrissur", 95.1]]}]')
